/bin/zsh -lc "printf '%s\\n' '--- directory ---'; ls -la; printf '%s\\n' '--- candidate executables ---'; command -v qloop || true; command -v qloops || true; printf '%s\\n' '--- local metadata ---'; find . -maxdepth 4 -type f -print 2>/dev/null; printf '%s\\n' '--- fetch schema and verify engine documents ---'; t="'$(mktemp -d /tmp/qfactory-contract.XXXXXX); curl -fsS http://localhost:3101/registry/schema.json -o "$t/schema.json"; node - "$t" <<'"'NODE'
const fs=require('fs'),path=require('path'),crypto=require('crypto');
const base=process.argv[2];
const origin='http://localhost:3101';
const engine=JSON.parse(require('child_process').execFileSync('curl',['-fsS',origin+'/registry/engine.json']));
const expected={}; for(const d of engine.documents) expected[d.file]=d.sha256;
for(const d of engine.documents){const out=path.join(base,d.file);fs.mkdirSync(path.dirname(out),{recursive:true});require('child_process').execFileSync('curl',['-fsS',origin+d.url],{stdio:['ignore',fs.openSync(out,'w'),'inherit']});const got=crypto.createHash('sha256').update(fs.readFileSync(out)).digest('hex');console.log("'`${d.file}'"\\t"'${got}'"\\t"'${got===d.sha256?'"'OK':'MISMATCH'}"'`)}
NODE
printf '"'%s\\n' '--- schema checksum ---'; sha256 -q \""'$t/schema.json"; printf '"'%s\\n' '--- contract workspace ---'; find \""'$t" -type f -maxdepth 5 -print'

